(67095, 1990, 142, '<td valign="top">I love the rays peaking through the clouds.  Great photo.</td>', 'I love the rays peaking through the clouds.  Great photo.', '2002-06-03 23:49:00.000000', NULL, 1),
(67096, 1990, 772, '<td valign="top">I like the way you have captured the sun rays falling throught he clouds in this shot... good work!</td>', 'I like the way you have captured the sun rays falling throught he clouds in this shot... good work!', '2002-06-04 00:34:00.000000', NULL, 1),
(67097, 1990, 1031, '<td valign="top">I shoot a lot of photos in this vein -- nice job! I like you caught those sunbeams in the left-center, and there''s a lot of nice texture in the dark clouds (especially considering he limitations of DPC!).</td>', 'I shoot a lot of photos in this vein -- nice job! I like you caught those sunbeams in the left-center, and there''s a lot of nice texture in the dark clouds (especially considering he limitations of DPC!).', '2002-06-04 03:48:00.000000', NULL, 1),
(67098, 1990, 1037, '<td valign="top">Great sky, but I wish there was some element that pulled the picture together and gave it a focus. A silhouette of something in there would have helped. I still rate it high though.</td>', 'Great sky, but I wish there was some element that pulled the picture together and gave it a focus. A silhouette of something in there would have helped. I still rate it high though.', '2002-06-04 04:19:00.000000', NULL, 1),
(67099, 1990, 1997, '<td valign="top">I think it is to dark and monotonous to catch the eye</td>', 'I think it is to dark and monotonous to catch the eye', '2002-06-04 08:11:00.000000', NULL, 1),
