(67665, 2044, 2103, '<td valign="top">not particularly</td>', 'not particularly', '2002-06-09 15:34:00.000000', NULL, 1),
(67666, 2044, 656, '<td valign="top">composition is quite static - maybe a diagonal would have more life ?</td>', 'composition is quite static - maybe a diagonal would have more life ?', '2002-06-09 22:07:00.000000', NULL, 1),
(67667, 2044, 1, '<td valign="top">Nice shot, great placement of the roses -- almost looks like a sketch.</td>', 'Nice shot, great placement of the roses -- almost looks like a sketch.', '2002-06-10 00:31:00.000000', NULL, 1),
(67668, 2044, 1707, '<td valign="top">Unlike some!, I have also a love for flowers, especially roses.  Reason why I rated this photo as a 10.  Because there is nothing else but 3 roses, I think it''s actually good to center them.   I also think you did an excellent job.  Will have to try myself!</td>', 'Unlike some!, I have also a love for flowers, especially roses.  Reason why I rated this photo as a 10.  Because there is nothing else but 3 roses, I think it''s actually good to center them.   I also think you did an excellent job.  Will have to try myself!', '2002-06-15 03:41:00.000000', NULL, 0),
(67669, 2044, 5257, '<td valign="top">this has been on my desktop ever since it got posted.. I love it!</td>', 'this has been on my desktop ever since it got posted.. I love it!', '2002-11-18 17:27:00.000000', NULL, 0),
