(67898, 2079, 1031, '<td valign="top">Relaxed kitty!</td>', 'Relaxed kitty!', '2002-06-05 18:37:00.000000', NULL, 1),
(67899, 2079, 1041, '<td valign="top">You chopped poor kittie''s ear off!!!  Other than that, I REALLY like the close-up and angle.</td>', 'You chopped poor kittie''s ear off!!!  Other than that, I REALLY like the close-up and angle.', '2002-06-06 13:32:00.000000', NULL, 1),
(67900, 2079, 2104, '<td valign="top">Hrm. I don''t quite like the composition of this, a bit too ordinary for my tastes. But its still a nice photograph - I especially like how kitty is looking out of the frame.</td>', 'Hrm. I don''t quite like the composition of this, a bit too ordinary for my tastes. But its still a nice photograph - I especially like how kitty is looking out of the frame.', '2002-06-09 14:59:00.000000', NULL, 1),
(67901, 2080, 1647, '<td valign="top">Nice framing, nice focus and nice DOF.  I particularly appreciate the fact that you took the photo from close to the ground.  I''m not sure if the flower adds or detracts from the image, but it is very good regardless</td>', 'Nice framing, nice focus and nice DOF.  I particularly appreciate the fact that you took the photo from close to the ground.  I''m not sure if the flower adds or detracts from the image, but it is very good regardless', '2002-06-03 01:41:00.000000', NULL, 1),
(67902, 2080, 1829, '<td valign="top">Graveyards always look great in B&amp;W.  You captured this shot well.</td>', 'Graveyards always look great in B&W.  You captured this shot well.', '2002-06-03 07:02:00.000000', NULL, 1),
(67903, 2080, 1211, '<td valign="top">Nice cropping on this one.</td>', 'Nice cropping on this one.', '2002-06-03 12:31:00.000000', NULL, 1),
