(68170, 2097, 1944, '<td valign="top">excellent</td>', 'excellent', '2002-06-03 13:54:00.000000', NULL, 1),
(68171, 2097, 2, '<td valign="top">Wonderful lighting, and a very cool subject.  I really love the depth you''ve acheived in this image.</td>', 'Wonderful lighting, and a very cool subject.  I really love the depth you''ve acheived in this image.', '2002-06-03 14:35:00.000000', NULL, 1),
(68172, 2097, 1759, '<td valign="top">Nice photo and an original idea that works well for B&amp;W. What I might suggest, though somewhat reservedly, is a tough of light from the right and brush the little bit of dust from the shell and the leaf. Maybe a reflector would make an improvement, I don''t know for sure about that. However, in my opinion this is already an excellent photo.</td>', 'Nice photo and an original idea that works well for B&W. What I might suggest, though somewhat reservedly, is a tough of light from the right and brush the little bit of dust from the shell and the leaf. Maybe a reflector would make an improvement, I don''t know for sure about that. However, in my opinion this is already an excellent photo.', '2002-06-03 15:09:00.000000', NULL, 1),
(68173, 2097, 1211, '<td valign="top">I wish the light was coming from the right and not the left for better detail on the snail.  The bottow also is out of focus and that is distracting a bit.</td>', 'I wish the light was coming from the right and not the left for better detail on the snail.  The bottow also is out of focus and that is distracting a bit.', '2002-06-03 16:23:00.000000', NULL, 1),
