(68929, 2141, 1313, '<td valign="top">Nice pic</td>', 'Nice pic', '2002-06-03 20:48:00.000000', NULL, 1),
(68930, 2141, 1031, '<td valign="top">Good subject...I''d have tried to keep the upper part of the bridge a little darker, partly to help bring out the interior trusswork.</td>', 'Good subject...I''d have tried to keep the upper part of the bridge a little darker, partly to help bring out the interior trusswork.', '2002-06-04 02:57:00.000000', NULL, 1),
(68931, 2141, 587, '<td valign="top">reminds me of The Bridges of Madison County - would like it to have been a little sharper, but is still really nice. good job.</td>', 'reminds me of The Bridges of Madison County - would like it to have been a little sharper, but is still really nice. good job.', '2002-06-04 23:09:00.000000', NULL, 1),
